extends Node

## Inventory system — fully decoupled.
## Listens to EventBus.item_picked_up and EventBus.item_used.
## Emits EventBus.inventory_changed on every mutation.
## Emits EventBus.inventory_full when at capacity and a new item is refused.

@export var max_slots: int = 8

var _items: Dictionary = {}  # item_id (StringName) -> quantity (int)


func _ready() -> void:
	EventBus.item_picked_up.connect(_on_item_picked_up)
	EventBus.item_used.connect(_on_item_used)


func _on_item_picked_up(item_id: StringName, quantity: int) -> void:
	if item_id in _items:
		_items[item_id] += quantity
	else:
		if _items.size() >= max_slots:
			EventBus.inventory_full.emit()
			return
		_items[item_id] = quantity
	EventBus.inventory_changed.emit(_snapshot())


func _on_item_used(item_id: StringName) -> void:
	if not item_id in _items:
		return
	_items[item_id] -= 1
	if _items[item_id] <= 0:
		_items.erase(item_id)
	EventBus.inventory_changed.emit(_snapshot())


func _snapshot() -> Dictionary:
	# Return a copy so callers can't mutate internal state.
	return _items.duplicate()

extends Area2D

## A pickup item that emits EventBus.item_picked_up when a player body enters.
## Fully decoupled — never references Inventory or Hotbar class names.

@export var item_id: StringName = &""
@export var quantity: int = 1


func _on_body_entered(body: Node2D) -> void:
	if not body.is_in_group("player"):
		return
	EventBus.item_picked_up.emit(item_id, quantity)
	queue_free()

extends Control

## Hotbar UI that renders inventory contents.
## Subscribes to EventBus.inventory_changed.
## Fully decoupled — never references Inventory or Pickup class names.

const MAX_SLOTS: int = 8


func _ready() -> void:
	EventBus.inventory_changed.connect(_on_inventory_changed)
	# Hide all labels initially.
	for i in range(MAX_SLOTS):
		var label: Label = _get_slot_label(i)
		if label:
			label.hide()


func _on_inventory_changed(snapshot: Dictionary) -> void:
	var keys: Array = snapshot.keys()
	for i in range(MAX_SLOTS):
		var label: Label = _get_slot_label(i)
		if not label:
			continue
		if i < keys.size():
			var item_id: StringName = keys[i]
			var qty: int = snapshot[item_id]
			label.text = str(item_id) + " x" + str(qty)
			label.show()
		else:
			label.hide()


func _get_slot_label(index: int) -> Label:
	# Child nodes are named "Slot0", "Slot1", etc.
	return get_node_or_null("Slot%d" % index) as Label

